from itertools import combinations
S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
tiles=[]
for r in range(3):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for sub in [sq]+[sq-{p} for p in sq]:
   if sub<=S: tiles.append((sub,'sq' if len(sub)==4 else 'L', (r,c)))
# enumerate exact covers recursively
bycell={p:[t for t in tiles if p in t[0]] for p in S}
solutions=[]
def go(rem,chosen):
 if not rem:
  solutions.append(chosen); return
 p=min(rem)
 for tile in bycell[p]:
  if tile[0]<=rem: go(rem-tile[0],chosen+[tile])
go(S,[])
print('solutions',len(solutions))
from collections import Counter
print(Counter(tuple(sorted(Counter(t[1] for t in sol).items())) for sol in solutions))
for sol in solutions[:12]: print([(typ,pos,sorted(cells)) for cells,typ,pos in sol])
